svg.script:
var V = (typeof visb_vars !== "undefined") ? visb_vars : (window.visb_vars = {});
if (V["SEL"] === undefined) V["SEL"] = "0";
if (V["TARGET"] === undefined) V["TARGET"] = "NONE";
var selHand = null, selSlot = null;
function paint(id, color, w) {
  var e = document.getElementById(id);
  if (e) { e.setAttribute("stroke", color); e.setAttribute("stroke-width", w); }
}
function onHand(ev) {
  var m = /^hand_(P[12])_(\d+)$/.exec(ev.target.id || "");
  if (!m) return;
  if (selHand) paint(selHand, "none", "0");
  V["SEL"] = m[2];
  selHand = "hand_" + m[1] + "_" + m[2];
  paint(selHand, "#eadb51", "1.5");
}
function onSlot(name) {
  if (selSlot) paint(selSlot, "none", "0");
  V["TARGET"] = name;
  selSlot = "slot_" + name;
  paint(selSlot, "#eadb51", "1.5");
  setTimeout(function () {
    V["SEL"] = "0";
    if (selHand) { paint(selHand, "none", "0"); selHand = null; }
  }, 150);
}
